      continue;
    }
    if (!await store.isEmptyAppDir(entry.id)) continue;
    try {
      final files = await catalog.downloadWidgetHealing(entry);
      await store.installWidget(
        id: entry.id,
        version: entry.version,
        files: files,
      );
      updated.add(entry.id);
      AppLog.i(
        'apps',
        'healed broken install of ${entry.id} '
