  /// no absolute form, no NUL. This is the AC4 floor — `../x`, `a/../b`
  /// and `/abs` are all false, so `apps/<id>` cannot leave `apps/`.
  static bool isResolvableId(String id) =>
      id.isNotEmpty &&
      !id.contains('/') &&
      !id.contains('\\') &&
      !id.contains('\u0000') &&
      id != '.' &&
