  static String manifestPath(String id) => appFile(id, manifestFile);

  /// The app's boot entry path ([entry] defaults to the manifest
  /// namespace's [defaultEntry]).
  static String entryPath(String id, [String entry = defaultEntry]) =>
      appFile(id, entry);
